import{_ as t,c as a,o,ag as r}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"3POB Support","description":"","frontmatter":{"title":"3POB Support"},"headers":[],"relativePath":"general/3pob-support.md","filePath":"general/3pob-support.md","lastUpdated":null}'),s={name:"general/3pob-support.md"};function n(p,e,i,u,l,c){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_3pob-support" tabindex="-1">3POB Support <a class="header-anchor" href="#_3pob-support" aria-label="Permalink to &quot;3POB Support&quot;">​</a></h1><h2 id="requesting-3pob-support-for-product-creation" tabindex="-1">Requesting 3POB Support for Product Creation <a class="header-anchor" href="#requesting-3pob-support-for-product-creation" aria-label="Permalink to &quot;Requesting 3POB Support for Product Creation&quot;">​</a></h2><p>With changes to 3POB, this information might be slightly outdated; however, the products that 3POB can create can be extremely beneficial to the creation of products, including PAI amplification banners.</p><p>3POB was a major help in assisting with the creation of PAI amplification products.</p><h3 id="challenges" tabindex="-1">Challenges <a class="header-anchor" href="#challenges" aria-label="Permalink to &quot;Challenges&quot;">​</a></h3><p>It can be difficult for them to edit AI-generated content.</p><h3 id="steps-to-request-support" tabindex="-1">Steps to Request Support <a class="header-anchor" href="#steps-to-request-support" aria-label="Permalink to &quot;Steps to Request Support&quot;">​</a></h3><h3 id="step-1-navigate-to-the-3pob-portal" tabindex="-1">STEP 1: Navigate to the 3POB Portal <a class="header-anchor" href="#step-1-navigate-to-the-3pob-portal" aria-label="Permalink to &quot;STEP 1: Navigate to the 3POB Portal&quot;">​</a></h3><p>Request an account at the following link: <a href="https://mpc-prt.socom.mil/servicedesk/customer/user/login?destination=user%2Frequests%3Fstatus%3Dopen" target="_blank" rel="noreferrer">Log in - Service project (socom.mil)</a>.</p><h3 id="step-2-fill-out-the-product-request-form" tabindex="-1">STEP 2: Fill Out the Product Request Form <a class="header-anchor" href="#step-2-fill-out-the-product-request-form" aria-label="Permalink to &quot;STEP 2: Fill Out the Product Request Form&quot;">​</a></h3><p>Fill out the product request form attached to this page. Be as specific as possible so that they can create the best possible product. The turnaround could be between 2 to 7 days, depending on the urgency and your communication with the artist assigned to creating your product. You can attach any documents that can help them understand the product you want to create, as well as online references you found on search engines such as Google Images. Attached will be a screenshot of an unclassified version of the PAI amplification one-slider that you can copy.</p><p><a href="#">Request Sheet Template</a></p><p><a href="https://mpc-prt.socom.mil/servicedesk/customer/user/login?destination=user%2Frequests%3Fstatus%3Dopen" target="_blank" rel="noreferrer">3POB LINK HERE</a></p><p>[Support] [Creation]</p><p>[Required]</p>',15)])])}const f=t(s,[["render",n]]);export{d as __pageData,f as default};
